import { expect, expectStatus, test, uniqueName, type APIRequestContext } from "../../fixtures";

// Assumptions about the seeded test setup (not visible in the provided files):
// - Uploaded document text is parsed for an expiry date, so the insurance certificate
//   embeds yesterday's date as its policy expiry.
// - Extraction runs asynchronously; a document leaves "processing" once extracted.

const SUBMIT_POLL_ATTEMPTS = 60;
const POLL_INTERVAL_MS = 500;

function yesterdayIso(): string {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

async function uploadDocument(
  api: APIRequestContext,
  vendorId: string,
  kind: "w9" | "insurance_certificate" | "contract",
  content: string,
): Promise<string> {
  const response = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}.txt`,
        mimeType: "text/plain",
        buffer: Buffer.from(content),
      },
    },
  });
  const doc = await expectStatus<{ id: string }>(response, 201);
  return doc.id;
}

async function waitForExtracted(api: APIRequestContext, documentId: string): Promise<void> {
  for (let attempt = 0; attempt < SUBMIT_POLL_ATTEMPTS; attempt++) {
    const response = await api.get(`/api/documents/${documentId}`);
    const doc = await expectStatus<{ status: string }>(response, 200);
    if (doc.status !== "processing") {
      expect(doc.status).toBe("extracted");
      return;
    }
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }
  throw new Error(`Document ${documentId} did not finish extraction in time`);
}

test.describe("review vendors", () => {
  test(
    "an expired insurance certificate cannot be approved",
    { tag: "@REV-07" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor with a unique name and uploads all three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV-07 Expired Cert Vendor"),
          category: "services",
          contact_email: `rev07-${Date.now()}@vendor.test`,
        },
      });
      const vendor = await expectStatus<{ id: string }>(vendorResponse, 201);

      const expiry = yesterdayIso();
      const w9Id = await uploadDocument(member, vendor.id, "w9", "Form W-9 for test vendor.");
      const insuranceId = await uploadDocument(
        member,
        vendor.id,
        "insurance_certificate",
        `Certificate of insurance. Policy expires: ${expiry}.`,
      );
      const contractId = await uploadDocument(member, vendor.id, "contract", "Master services contract.");

      for (const documentId of [w9Id, insuranceId, contractId]) {
        await waitForExtracted(member, documentId);
      }

      // Submit: the vendor moves into review once all three documents are extracted.
      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);
      const submitted = await expectStatus<{ status: string }>(submitResponse, 200);
      expect(submitted.status).toBe("in_review");

      // Locate the insurance certificate's extraction.
      const extractionResponse = await member.get(`/api/documents/${insuranceId}/extraction`);
      const extraction = await expectStatus<{ id: string; status: string }>(extractionResponse, 200);
      expect(extraction.status).toBe("pending_review");

      // Act: the reviewer attempts to approve the expired certificate.
      const decisionResponse = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert: the approval is refused with insurance_expired.
      const body = await expectStatus<{ error: { code: string } }>(decisionResponse, 409);
      expect(body.error.code).toBe("insurance_expired");
    },
  );
});
